question:
What does this LINQ query return?
var nums = new[] { 1, 2, 3, 4, 5 };
var result = nums.Where(x => x > 2);
Console.WriteLine(result.Count());

What is deferred execution in LINQ?
var nums = new[] { 1, 2, 3 };
var query = nums.Where(x => {
  Console.WriteLine(x);
  return x > 1;
});
var result = query.ToList();

What does this Select query do?
var nums = new[] { 1, 2, 3 };
var result = nums.Select(x => x * 2).ToList();
Console.WriteLine(result[0]);

What does OrderBy return?
var nums = new[] { 3, 1, 4, 1, 5 };
var result = nums.OrderBy(x => x).ToList();
Console.WriteLine(result[0]);

What does First() return?
var nums = new[] { 1, 2, 3 };
var result = nums.First(x => x > 2);
Console.WriteLine(result);

What does Any() return?
var nums = new[] { 1, 2, 3 };
Console.WriteLine(nums.Any(x => x > 5));

What does Distinct() do?
var nums = new[] { 1, 2, 2, 3, 3, 3 };
var result = nums.Distinct().Count();
Console.WriteLine(result);

What does GroupBy return?
var nums = new[] { 1, 2, 2, 3, 3, 3 };
var groups = nums.GroupBy(x => x).Count();
Console.WriteLine(groups);

What does Join do?
var nums1 = new[] { 1, 2, 3 };
var nums2 = new[] { 2, 3, 4 };
var result = nums1.Join(nums2, x => x, y => y, (x, y) => x).Count();
Console.WriteLine(result);

What does Sum return?
var nums = new[] { 1, 2, 3, 4 };
Console.WriteLine(nums.Sum());
